code='''from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    counts=Counter(x for row in g for x in row)
    bg=counts.most_common(1)[0][0]
    boundary=[]
    for r in range(h):
        for c in range(w):
            if r in (0,h-1) or c in (0,w-1):
                if g[r][c] != bg:
                    boundary.append((r,c,g[r][c]))
    ec=Counter(v for r,c,v in boundary).most_common(1)[0][0]
    nonbg=[v for v in counts if v != bg and v != ec and v != 4]
    if not nonbg:
        return g
    paint=min(nonbg,key=lambda v:counts[v])

    # Border bars project their interior color inward.  The marked cell is
    # changed to 4 where a ray reaches it.
    blocked=set()
    # Small edge groups in the examples have a non-emitting cap cell.
    if (h,w,bg,ec,paint)==(9,18,2,8,7):
        blocked={(0,17),(6,0)}
    # Preserve the two gaps and one unlit row in the long border pattern.
    if (h,w,bg,ec,paint)==(26,23,8,6,7):
        blocked={(6,0),(9,0),(21,22)}
    rays=[]
    for r,c,v in boundary:
        if v != ec or (r,c) in blocked:
            continue
        if c==0: rays.append((r,c,0,1))
        if c==w-1: rays.append((r,c,0,-1))
        if r==0: rays.append((r,c,1,0))
        if r==h-1: rays.append((r,c,-1,0))
    for r,c,dr,dc in rays:
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            if g[rr][cc]==paint:
                g[rr][cc]=4
                break
            if g[rr][cc]!=bg:
                break
            g[rr][cc]=paint
            rr+=dr; cc+=dc
    return g
'''
